import axios from "axios";

const API_URL = "http://localhost:5000/api";

export const getProducts = () => axios.get(`${API_URL}/products`);

export const register = (data) => axios.post(`${API_URL}/auth/register`, data);
export const login = (data) => axios.post(`${API_URL}/auth/login`, data);

export const addToCart = async (productId) => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");

  return axios.post(`${API_URL}/cart`, {
    userId: user._id,
    productId,
    qty: 1,
  });
};

export const getCart = (userId) => axios.get(`${API_URL}/cart/${userId}`);
export const deleteCartItem = (id) => axios.delete(`${API_URL}/cart/${id}`);
export const clearCart = (userId) => axios.delete(`${API_URL}/cart/clear/${userId}`);
export const checkout = (cartItems) =>
  axios.post(`${API_URL}/checkout`, { cartItems });
